import java.util.Scanner;

public class Main {
    static long total = 0;

    static int countDigits(long number) {
        int count = 0;
        while (number != 0) {
            number /= 10;
            count++;
        }
        return count;
    }

    static long getBase(long number) {
        int digits = countDigits(number);
        long base = 0, multiplier = 1;
        for (int i = 0; i < digits; i++) {
            base += multiplier;
            multiplier *= 10;
        }
        if (base <= number) return base;
        return (base - 1) / 10;
    }

    static long compute(long number) {
        if (number <= 6) return number;
        if (number <= 11) return 13 - number;
        long baseNum = getBase(number);
        long boundary = baseNum * 10 + 1;
        if (number % baseNum == 0) {
            long quotient = number / baseNum;
            if (number <= boundary / 2 + baseNum) return countDigits(baseNum) * quotient;
            else {
                long diff = compute(boundary - number);
                return countDigits(boundary) + diff;
            }
        } else {
            long lower = (number / baseNum) * baseNum;
            long upper = (number / baseNum + 1) * baseNum;
            long res = compute(lower) + compute(number - lower);
            if (number > boundary / 2) {
                res = Math.min(compute(lower) + compute(number - lower), countDigits(boundary) + compute(boundary - number));
            }
            return res;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        System.out.println(compute(n));
        scanner.close();
    }
}
